insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:area:4', 'catalog:pmdf-cfo', 'area', 'resumo_proprio', 'Atualidades e Legislação Aplicada à PMDF', '', '', NULL, '', '', 'Matéria da trilha', '', 4, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
