insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:1', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Como estudar o CFO da PMDF', 'A seleção do CFO combina provas objetivas e discursiva, além de fases eliminatórias (aptidão física, exames médicos, avaliação psicológica e sindicância de vida pregressa/investigação social).

Estratégia inicial sugerida: (1) domine Português e Raciocínio Lógico, que sustentam a nota objetiva; (2) construa base sólida de Direito Constitucional (princípios do art. 37 e direitos do art. 5º); (3) trate a história e geografia do DF como matéria de memorização ativa com revisão espaçada; (4) treine a redação/discursiva semanalmente.

Este material é introdutório e autoral; não substitui o edital oficial.', '', NULL, '', '', 'Orientação de estudo (conteúdo comum de preparação)', '', 1, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:2', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Nota — Língua Portuguesa: coesão e coerência', 'Coesão é a amarração formal entre partes do texto (conectivos, pronomes, repetições controladas). Coerência é a relação lógica de sentido com o contexto.

Principais conectivos: adição (além disso, outrossim), oposição (porém, todavia, contudo), causa (porque, visto que), conclusão (portanto, logo), explicação (isto é, ou seja).

Erro comum de prova: confundir "mas" (oposição) com "mais" (quantidade) e "há" (tempo passado/existir) com "a" (distância/futuro do presente). Verifique sempre a função na frase.', '', NULL, '', '', 'Conteúdo comum de preparação', '', 2, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:3', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Nota — Raciocínio Lógico: proposições e conectivos', 'Proposição é sentença à qual se pode atribuir verdadeiro (V) ou falso (F). Conectivos principais:

- Conjunção (p ∧ q): V só quando ambos V.
- Disjunção (p ∨ q): F só quando ambos F.
- Condicional (p → q): F só quando p=V e q=F ("o antecedente verdadeiro com consequente falso").
- Bicondicional (p ↔ q): V quando ambos têm o mesmo valor.

Equivalência da condicional: p → q equivale a ¬q → ¬p (contrapositiva) e a ¬p ∨ q.

Erro comum: negar uma condicional como se fosse outra condicional. A negação de p → q é p ∧ ¬q.', '', NULL, '', '', 'Conteúdo comum de preparação', '', 3, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:4', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Nota — Direito Constitucional: princípios do art. 37', 'O art. 37 fixa os princípios expressos da administração pública: legalidade, impessoalidade, moralidade, publicidade e eficiência (LIMPE).

- Legalidade (para a Administração): só pode agir conforme a lei.
- Impessoidade: sem favorecimento pessoal.
- Moralidade: exige ética e boa-fé administrativa.
- Publicidade: transparência, com exceções legais (segurança do Estado/sociedade).
- Eficiência: incluir pela EC 19/1998.

Ponto de prova: o rol é exemplificativo? Não — estes cinco são os expressos no caput; há outros princípios implícitos no ordenamento.', '', NULL, '', '', 'Constituição Federal de 1988, art. 37', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 4, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:5', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Nota — História e Geografia do DF: noções introdutórias', 'O Distrito Federal foi criado pela Constituição de 1891 e implantado em 1960 com a inauguração de Brasília. Não é estado nem município: é uma unidade federativa com competências híbridas (Lei Orgânica no lugar de Constituição estadual).

Aspectos frequentemente cobrados: Plano Piloto e o tombamento como Patrimônio Cultural da Humanidade (UNESCO, 1987); Regiões Administrativas; limites com Goiás e Minas Gerais; clima tropical com estação seca no inverno.

Dica de revisão: use mapa e linha do tempo; memorize marcos (1891, 1956 início da construção, 1960 inauguração, 1987 tombamento).', '', NULL, '', '', 'Conteúdo comum de preparação', '', 5, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:flashcard:20', 'catalog:pmdf-cfo', 'flashcard', 'flashcard', 'Flashcard — Níveis de análise da segurança pública (art. 144)', 'Frente: Segundo o art. 144 da CF/88, a segurança pública é dever de quem, além de direito e responsabilidade de quem?

Verso: É dever do Estado e direito e responsabilidade de todos.', '', NULL, '', '', 'Constituição Federal de 1988, art. 144', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 20, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:flashcard:21', 'catalog:pmdf-cfo', 'flashcard', 'flashcard', 'Flashcard — Princípios expressos do art. 37', 'Frente: Cite os cinco princípios expressos da administração pública no art. 37 da CF/88.

Verso: Legalidade, impessoalidade, moralidade, publicidade e eficiência (LIMPE).', '', NULL, '', '', 'Constituição Federal de 1988, art. 37', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 21, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:flashcard:22', 'catalog:pmdf-cfo', 'flashcard', 'flashcard', 'Flashcard — Negação da condicional', 'Frente: Qual é a negação lógica da proposição p → q?

Verso: p ∧ ¬q (o antecedente verdadeiro e o consequente falso).', '', NULL, '', '', 'Raciocínio lógico (conteúdo comum)', '', 22, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:flashcard:23', 'catalog:pmdf-cfo', 'flashcard', 'flashcard', 'Flashcard — Distrito Federal é estado ou município?', 'Frente: O Distrito Federal é um estado ou um município?

Verso: Nem um nem outro: é uma unidade federativa com competências híbridas, regida por Lei Orgânica.', '', NULL, '', '', 'Conteúdo comum de preparação', '', 23, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:flashcard:24', 'catalog:pmdf-cfo', 'flashcard', 'flashcard', 'Flashcard — Coesão x coerência', 'Frente: Qual a diferença entre coesão e coerência textual?

Verso: Coesão é a ligação formal (conectivos/pronomes ordenando as partes); coerência é a relação lógica de sentido com o contexto.', '', NULL, '', '', 'Língua Portuguesa (conteúdo comum)', '', 24, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:100', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-01', 'Sobre os princípios expressos da administração pública no art. 37 da CF/88, assinale a alternativa correta.', '["São apenas legalidade e impessoalidade.","São: legalidade, impessoalidade, moralidade, publicidade e eficiência.","A eficiência não consta do texto constitucional.","O rol é taxativo e impede outros princípios.","A moralidade foi revogada pela EC 19/1998."]', 1, 'O caput do art. 37 lista os cinco princípios expressos (LIMPE). A eficiência foi incluída pela EC 19/1998; o rol não impede princípios implícitos.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 100, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:101', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-02', 'A negação lógica da proposição "Se estudo, então sou aprovado" é:', '["Se não estudo, então não sou aprovado.","Se sou aprovado, então estudo.","Estudo e não sou aprovado.","Não estudo e sou aprovado.","Estudo ou sou aprovado."]', 2, 'A negação da condicional p → q é p ∧ ¬q: "Estudo E não sou aprovado". A alternativa ''a'' é a inversa (não equivalente) e a ''b'' é a recíproca.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 101, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:102', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-03', 'Segundo o art. 144 da Constituição Federal de 1988, a segurança pública é:', '["responsabilidade exclusiva da União.","dever do Estado, direito e responsabilidade de todos.","atribuição apenas das polícias militares.","matéria infraconstitucional, sem previsão na CF.","competência exclusiva do Distrito Federal."]', 1, 'O caput do art. 144 afirma que a segurança pública é dever do Estado, direito e responsabilidade de todos, exercida pelos órgãos ali listados.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 102, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:103', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-04', 'O Distrito Federal, no plano político-administrativo, é:', '["um município com prefeito e câmara.","um estado federado com Constituição própria.","uma unidade federativa regida por Lei Orgânica, sem subdivisão municipal.","um território federal administrado pela União.","parte integrante do estado de Goiás."]', 2, 'O DF não é estado nem município: é unidade federativa regida por Lei Orgânica, com competências legislativas híbridas.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 103, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:104', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-05', 'Assinale a alternativa em que há ERRO no uso dos conectivos/ortografia.', '["Estudei muito, portanto fui aprovado.","Quero mais tempo, mas o edital é curto.","Há dois anos ele estuda para o concurso.","Ele estuda mas cedo do que eu.","Não fui à prova porque adoeci."]', 3, 'Em ''mais cedo'' deve-se usar o advérbio ''mais''. ''Mas'' é conjunção adversativa; ''mas cedo'' está incorreto.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 104, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:105', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-06', 'Em relação à condicional (p → q), é correto afirmar que ela é falsa:', '["somente quando p é falso e q é verdadeiro.","somente quando p é verdadeiro e q é falso.","somente quando ambos são verdadeiros.","somente quando ambos são falsos.","em nenhuma hipótese."]', 1, 'A condicional só é falsa no caso V → F, ou seja, antecedente verdadeiro e consequente falso.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 105, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:106', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-07', 'Sobre a prova discursiva e as fases do CFO da PMDF, é correto dizer que:', '["há apenas prova objetiva.","a investigação social não existe em concurso de carreira policial.","há fases eliminatórias como aptidão física, exames médicos, avaliação psicológica e sindicância de vida pregressa.","a discursiva é classificatória, mas não eliminatória.","o curso de formação não integra o concurso."]', 2, 'O concurso do CFO inclui fases eliminatórias (TAF, exames médicos, avaliação psicológica) e sindicância de vida pregressa/investigação social, além de objetiva e discursiva.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 106, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:107', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-08', 'A coerência textual diz respeito a:', '["ao uso exclusivo de conectivos.","à relação lógica de sentido entre as partes e o contexto.","apenas à correção ortográfica.","ao número de parágrafos.","à pontuação isolada."]', 1, 'Coerência é a relação lógica de sentido; coesão é a ligação formal (conectivos, pronomes).', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 107, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:108', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-09', 'O tombamento de Brasília como Patrimônio Cultural da Humanidade ocorreu em:', '["1960","1987","1891","2000","1975"]', 1, 'A UNESCO reconheceu o Plano Piloto como Patrimônio Cultural da Humanidade em 1987.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 108, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:questao:109', 'catalog:pmdf-cfo', 'questao', 'questao_autoral', 'Questão autoral PMDF-10', 'Sobre cláusulas pétreas (art. 60, § 4º), os direitos e garantias individuais do art. 5º:', '["podem ser abolidos por emenda constitucional.","não integram as cláusulas pétreas.","não podem ser abolidos por emenda tendente a aboli-los.","foram revogados pela EC 45/2004.","dependem de lei complementar para valer."]', 2, 'Os direitos e garantias individuais são cláusula pétrea: não podem ser abolidos nem sofrer emenda tendente a aboli-los.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 109, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pmdf-cfo:nota:90', 'catalog:pmdf-cfo', 'nota', 'resumo_proprio', 'Ficha — Constituição Federal de 1988: arts. 5º, 37 e 144', 'Resumo de estudo dos dispositivos mais recorrentes em provas de carreiras policiais. O texto entre aspas é citação literal da redação oficial; o restante é explicação didática de autoria própria.

Art. 5º — Direitos e garantias individuais. "Todos são iguais perante a lei, sem distinção de qualquer natureza..." Abrange a inviolabilidade da vida, liberdade, igualdade, segurança e propriedade. É cláusula pétrea (art. 60, § 4º). Ponto de prova: o caput é exemplificativo, não taxativo (art. 5º, § 2º).

Art. 37 — Administração pública. Estabelece os princípios expressos: "legalidade, impessoalidade, moralidade, publicidade e eficiência". A eficiência foi incluída pela EC 19/1998. Costuma aparecer combinado com os princípios implícitos (razoabilidade, proporcionalidade, motivação) e com a Lei 8.429/1992 (improbidade).

Art. 144 — Segurança pública. "A segurança pública, dever do Estado, direito e responsabilidade de todos..." Lista os órgãos responsáveis, entre eles a polícia federal, a polícia rodoviária federal e as polícias militares. Ponto de prova: segurança pública é dever do Estado, mas também direito e responsabilidade de todos.

Checagem de aprendizagem: (1) Quais são os cinco princípios expressos do art. 37? (2) O art. 144 caput trata a segurança pública como direito de quem? (3) O art. 5º é cláusula pétrea?', '', NULL, '', '', 'Constituição Federal de 1988', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 90, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;

