insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:area:5', 'catalog:pf-policial-2025', 'area', 'resumo_proprio', 'Legislação Especial e Direitos Humanos', '', '', NULL, '', '', 'Matéria da trilha', '', 5, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:1', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Como estudar a carreira policial da PF', 'O Edital nº 1 - PF - Policial (20/05/2025) abrange, entre outros, os cargos de Delegado, Perito Criminal Federal, Escrivão, Agente e Papiloscopista Policial Federal. Para Agente, Escrivão e Papiloscopista, a prova objetiva traz um bloco de Conhecimentos Básicos (Bloco I) com 60 itens, além de prova discursiva; a Investigação Social é etapa eliminatória.

Estratégia: (1) garanta o Bloco I, reprovando notas abaixo do mínimo; (2) integre Direito Penal, Processual Penal e Legislação Especial, muito cobrados; (3) mantenha Informática e Raciocínio Lógico com treino de questões; (4) treine a discursiva com temas de direitos humanos e segurança pública.

Material introdutório e autoral; não substitui o edital.', '', NULL, '', '', 'Orientação de estudo (base: edital 2025)', '', 1, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:2', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Nota — Direito Penal: princípio da legalidade', 'O princípio da legalidade (art. 1º do CP) exige que não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal (nullum crimen, nulla poena sine lege). Dois desdobramentos:

- Anterioridade: a lei deve ser prévia ao fato.
- Reserva legal: lei em sentido estrito.

A lei penal não retroage, salvo para beneficiar o réu (CF, art. 5º, XL).

Erro comum: confundir legalidade com atipicidade. A atipicidade é a consequência de o fato não se encaixar no tipo penal, ainda que exista lei.', '', NULL, '', '', 'Código Penal, art. 1º; CF/88, art. 5º, XXXIX', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 2, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:3', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Nota — Direito Processual Penal: inquérito policial', 'O inquérito policial é procedimento administrativo, inquisitivo, escrito, destinado a apurar a materialidade e a autoria de infração penal, conduzido pela polícia judiciária.

Características: dispensável (o MP pode oferecer denúncia com outros elementos), sigiloso quanto a terceiros, indisponível (a autoridade não pode arquivar). Prazo: em regra 10 dias se preso e 30 dias se solto.

Ponto de prova: o inquérito não se presta ao contraditório pleno; a defesa atua de modo limitado.', '', NULL, '', '', 'Código de Processo Penal, arts. 4º a 23', '', 3, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:4', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Nota — Direito Constitucional: remédios constitucionais', 'Remédios constitucionais mais cobrados:

- Habeas corpus (art. 5º, LXVIII): liberdade de locomoção; gratuito.
- Habeas data (LXXII): acesso/retificação de dados pessoais em registros públicos.
- Mandado de segurança (LXIX): direito líquido e certo não amparado por HC/HD.
- Mandado de injunção (LXXI): falta de norma regulamentadora.
- Ação popular (LXXIII): ato lesivo ao patrimônio público/moralidade/meio ambiente.

Erro comum: atribuir o habeas data à liberdade de locomoção. Locomoção é HC.', '', NULL, '', '', 'Constituição Federal de 1988, art. 5º', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 4, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:5', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Nota — Noções de Informática: segurança da informação', 'Princípios de segurança (CID): confidencialidade, integridade e disponibilidade. Termos frequentes em prova:

- Autenticação x autorização: provar identidade x conceder acesso.
- Criptografia simétrica (mesma chave) x assimétrica (par de chaves pública/privada).
- Assinatura digital: garante autenticidade e integridade (não sigilo por si só).
- Phishing, ransomware e engenharia social: ameaças comuns.

Dica: diferencie backup (cópia) de redundância (duplicação operacional).', '', NULL, '', '', 'Conteúdo comum de preparação', '', 5, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:flashcard:20', 'catalog:pf-policial-2025', 'flashcard', 'flashcard', 'Flashcard — Remédio para liberdade de locomoção', 'Frente: Qual remédio constitucional protege a liberdade de locomoção e é gratuito?

Verso: Habeas corpus (art. 5º, LXVIII).', '', NULL, '', '', 'Constituição Federal de 1988, art. 5º, LXVIII', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 20, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:flashcard:21', 'catalog:pf-policial-2025', 'flashcard', 'flashcard', 'Flashcard — Princípio da legalidade penal', 'Frente: O que significa nullum crimen, nulla poena sine lege?

Verso: Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.', '', NULL, '', '', 'Código Penal, art. 1º', '', 21, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:flashcard:22', 'catalog:pf-policial-2025', 'flashcard', 'flashcard', 'Flashcard — CID na segurança da informação', 'Frente: Quais são os três princípios básicos (CID) da segurança da informação?

Verso: Confidencialidade, Integridade e Disponibilidade.', '', NULL, '', '', 'Informática (conteúdo comum)', '', 22, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:flashcard:23', 'catalog:pf-policial-2025', 'flashcard', 'flashcard', 'Flashcard — Inquérito policial é dispensável?', 'Frente: O inquérito policial é peça indispensável para a denúncia?

Verso: Não. É dispensável; o MP pode denunciar com base em outros elementos.', '', NULL, '', '', 'Código de Processo Penal', '', 23, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:flashcard:24', 'catalog:pf-policial-2025', 'flashcard', 'flashcard', 'Flashcard — Anterioridade penal', 'Frente: A lei penal pode retroagir? Em que hipótese?

Verso: Em regra não; retroage apenas para beneficiar o réu.', '', NULL, '', '', 'Constituição Federal de 1988, art. 5º, XL', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 24, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:100', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-01', 'Assinale a alternativa que apresenta um remédio constitucional gratuito destinado a proteger a liberdade de locomoção.', '["Mandado de segurança","Habeas data","Habeas corpus","Ação popular","Mandado de injunção"]', 2, 'O habeas corpus (art. 5º, LXVIII) protege a liberdade de locomoção e é gratuito.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 100, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:101', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-02', 'Sobre o princípio da legalidade penal, é correto afirmar que:', '["basta decreto para criar crime.","não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.","a lei penal sempre retroage.","a medida provisória é o instrumento adequado para tipificar crimes.","a legalidade não se aplica às contravenções."]', 1, 'Legalidade penal (art. 1º do CP): exige lei anterior (reserva legal + anterioridade); retroação só em benefício do réu.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 101, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:102', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-03', 'O inquérito policial, segundo o CPP, é:', '["peça indispensável para o oferecimento da denúncia.","procedimento judicial contraditório pleno.","procedimento administrativo inquisitivo e dispensável.","ato exclusivo do Ministério Público.","instrumento que impede a defesa de qualquer acesso."]', 2, 'O IP é procedimento administrativo, inquisitivo e dispensável; não é plenamente contraditório.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 102, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:103', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-04', 'O princípio da disponibilidade da ação penal pública significa que:', '["o delegado pode arquivar o inquérito.","o inquérito é indisponível para a autoridade policial.","o MP pode arquivar a denúncia por conveniência.","a ação penal pública é de titularidade do ofendido.","não há ação penal pública no Brasil."]', 1, 'O inquérito policial é indisponível para a autoridade policial; quem pode promover o arquivamento é o MP, nos termos legais.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 103, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:104', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-05', 'Em segurança da informação, o princípio da integridade garante que:', '["a informação esteja sempre disponível.","a informação seja mantida correta e não alterada indevidamente.","os dados sejam públicos.","haja backup obrigatório.","o usuário seja autenticado por senha."]', 1, 'Integridade assegura que a informação seja mantida íntegra/inalterada indevidamente. Disponibilidade é o outro princípio (CID).', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 104, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:105', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-06', 'A assinatura digital de um documento tem como função principal:', '["cifrar o documento para torná-lo secreto.","garantir autenticidade e integridade do documento.","substituir a senha do usuário.","aumentar a velocidade da rede.","comprimir o arquivo."]', 1, 'A assinatura digital garante autenticidade e integridade; o sigilo é papel da criptografia, não da assinatura por si só.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 105, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:106', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-07', 'Sobre a Investigação Social no concurso da PF, é correto afirmar que:', '["é etapa classificatória, mas não eliminatória.","não existe no concurso da PF.","é etapa eliminatória.","só se aplica ao cargo de Delegado.","substitui a prova de aptidão física."]', 2, 'Conforme o edital, a Investigação Social é etapa eliminatória do certame.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 106, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:107', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-08', 'O habeas data destina-se a:', '["assegurar conhecimento/retificação de dados relativos à pessoa do impetrante em registros públicos.","proteger a liberdade de locomoção.","suprir falta de norma regulamentadora.","anular ato lesivo ao patrimônio público.","garantir o contraditório no inquérito."]', 0, 'O habeas data (art. 5º, LXXII) serve ao acesso/retificação de dados pessoais em registros de entidades governamentais ou de caráter público.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 107, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:108', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-09', 'Na distinção entre autenticação e autorização:', '["autenticação concede acesso; autorização prova identidade.","autenticação prova identidade; autorização concede acesso.","são sinônimos.","ambas se referem apenas a senhas.","autorização impede o login."]', 1, 'Autenticação é provar a identidade; autorização é definir o que aquele usuário pode acessar.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 108, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:questao:109', 'catalog:pf-policial-2025', 'questao', 'questao_autoral', 'Questão autoral PF-10', 'A redação do art. 144 da CF/88 trata a segurança pública como:', '["dever exclusivo das polícias civis.","dever do Estado, direito e responsabilidade de todos.","matéria não prevista na Constituição.","atribuição exclusiva da União.","responsabilidade apenas dos municípios."]', 1, 'Art. 144, caput: segurança pública é dever do Estado, direito e responsabilidade de todos.', 'Autoral/gerada para prática — NÃO é questão oficial.', 'Treino autoral', '', 109, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;
insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:pf-policial-2025:nota:90', 'catalog:pf-policial-2025', 'nota', 'resumo_proprio', 'Ficha — Constituição Federal de 1988: arts. 5º, 37 e 144', 'Resumo de estudo dos dispositivos mais recorrentes em provas de carreiras policiais. O texto entre aspas é citação literal da redação oficial; o restante é explicação didática de autoria própria.

Art. 5º — Direitos e garantias individuais. "Todos são iguais perante a lei, sem distinção de qualquer natureza..." Abrange a inviolabilidade da vida, liberdade, igualdade, segurança e propriedade. É cláusula pétrea (art. 60, § 4º). Ponto de prova: o caput é exemplificativo, não taxativo (art. 5º, § 2º).

Art. 37 — Administração pública. Estabelece os princípios expressos: "legalidade, impessoalidade, moralidade, publicidade e eficiência". A eficiência foi incluída pela EC 19/1998. Costuma aparecer combinado com os princípios implícitos (razoabilidade, proporcionalidade, motivação) e com a Lei 8.429/1992 (improbidade).

Art. 144 — Segurança pública. "A segurança pública, dever do Estado, direito e responsabilidade de todos..." Lista os órgãos responsáveis, entre eles a polícia federal, a polícia rodoviária federal e as polícias militares. Ponto de prova: segurança pública é dever do Estado, mas também direito e responsabilidade de todos.

Checagem de aprendizagem: (1) Quais são os cinco princípios expressos do art. 37? (2) O art. 144 caput trata a segurança pública como direito de quem? (3) O art. 5º é cláusula pétrea?', '', NULL, '', '', 'Constituição Federal de 1988', 'https://www4.planalto.gov.br/legislacao/portal-legis/legislacao-1/constituicao', 90, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
on conflict (collection_id, title, kind) do nothing;

-- Trilha: PRF — Policial Rodoviário Federal
insert into catalog_collections (id, slug, title, discipline_label, summary, status, status_note, source_name, source_url, edital_ref, checked_at, created_at, updated_at) values ('catalog:prf-policial', 'prf-policial', 'PRF — Policial Rodoviário Federal', 'Concursos', 'Trilha de preparação para o cargo de Policial Rodoviário Federal (PRF), Padrão I da Terceira Classe, com tópicos básicos e específicos.', 'historico', 'Baseado no Edital Concurso PRF nº 1, de 18/01/2021 (Cebraspe) — referência histórica do último edital oficial. A validade foi prorrogada por decisão judicial (Edital nº 119, de 18/06/2026, +6 meses). Não há, nesta verificação, novo edital de abertura confirmado; não trate este material como edital vigente.', 'Edital Concurso PRF nº 1, de 18/01/2021 (Cebraspe / PRF)', 'https://www.gov.br/prf/pt-br/acesso-a-informacao/servidores/concursos-e-selecoes/concurso-2021', 'Edital Concurso PRF nº 1, de 18/01/2021', '2026-10-20', '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
