insert into catalog_items (id, collection_id, kind, category, title, body, options_json, correct_index, explanation, origin_note, ref_label, url, sort_order, created_at, updated_at) values ('catalog:prf-policial:area:5', 'catalog:prf-policial', 'area', 'resumo_proprio', 'Ética no Serviço Público', '', '', NULL, '', '', 'Matéria da trilha', '', 5, '2026-10-21T11:59:18.024Z', '2026-10-21T11:59:18.024Z')
